function redemptionPayloadFromQr(value,currentUrl=location.href){
  const raw=String(value??'').trim();
  if(!raw)return {kind:'',token:''};
  if(/^[A-Za-z0-9_-]{20,512}$/.test(raw))return {kind:'classic',token:raw};
  const prefixed=raw.match(/^nestly:redemption:([A-Za-z0-9_-]{20,512})$/i);
  if(prefixed)return {kind:'classic',token:prefixed[1]};
  const growthPrefixed=raw.match(/^nestly:growth:([A-Za-z0-9_-]{20,512})$/i);
  if(growthPrefixed)return {kind:'growth',token:growthPrefixed[1]};
  try{
    const url=new URL(raw,currentUrl);
    const hashParams=new URLSearchParams((url.hash.split('?')[1]||''));
    const growthToken=url.searchParams.get('growth_token')||hashParams.get('growth_token')||'';
    const token=growthToken||url.searchParams.get('redemption')||url.searchParams.get('token')
      ||hashParams.get('redemption')||hashParams.get('token')||'';
    if(!/^[A-Za-z0-9_-]{20,512}$/.test(token))return {kind:'',token:''};
    const hashPath=(url.hash.split('?')[0]||'').toLowerCase();
    const kind=growthToken||hashPath==='#/growth-redeem'?'growth':'classic';
    return {kind,token};
  }catch{return {kind:'',token:''}}
}
function redemptionTokenFromQr(value,currentUrl=location.href){
  return redemptionPayloadFromQr(value,currentUrl).token;
}
function merchantRedemptionReceiptView(data={}){
  const kind=data.redemption_kind==='growth_offer'
    ?'growth_offer'
    :data.redemption_kind==='classic_points'?'classic_points':'catalog_reward';
  const creditCents=Math.max(0,Number(data.credit_cents||0));
  const offerValueCents=Math.max(0,Number(data.value_cents||0));
  const offerCurrency=String(data.currency||'').trim().toUpperCase();
  return {
    kind,
    customerName:String(data.customer_name||'Customer'),
    rewardLabel:String(data.reward_label||(kind==='classic_points'
      ?'Points to store credit'
      :kind==='growth_offer'?'Customer offer':'Reward')),
    pointsSpent:Math.max(0,Number(data.points_spent||0)),
    creditCents,
    offerValueCents,
    offerCurrency,
    operationId:String(data.operation_id||data.intent_id||data.entitlement_id||''),
    fulfilment:kind==='growth_offer'
      ?'This customer offer is now linked to the completed purchase. Provide the advertised benefit now if it was not already included in the sale.'
      :kind==='classic_points'
      ?`Store credit of ${money(creditCents)} has been added to the customer’s programme.`
      :'Provide the reward shown above to the customer now. The scan records the points redemption but does not hand over a physical item.'
  };
}
function merchantRedemptionReceiptHtml(data={}){
  const receipt=merchantRedemptionReceiptView(data);
  return `<div class="row"><div><h2 id="merchantScannerTitle">Redemption confirmed</h2><p class="muted small" style="margin-top:5px">Server receipt for this completed scan.</p></div><span class="spacer"></span><span class="pill ok">Completed</span></div>
    <dl class="receipt-detail" style="margin-top:16px">
      <div><dt>Customer</dt><dd>${esc(receipt.customerName)}</dd></div>
      <div><dt>Reward</dt><dd>${esc(receipt.rewardLabel)}</dd></div>
      ${receipt.kind==='growth_offer'?'':`<div><dt>Points spent</dt><dd>${receipt.pointsSpent}</dd></div>`}
      ${receipt.creditCents?`<div><dt>Store credit</dt><dd>${esc(money(receipt.creditCents))}</dd></div>`:''}
      ${receipt.offerValueCents&&receipt.offerCurrency
        ?`<div><dt>Offer value</dt><dd>${esc(`${receipt.offerCurrency} ${(receipt.offerValueCents/100).toFixed(2)}`)}</dd></div>`
        :''}
      <div><dt>Operation reference</dt><dd><code>${esc(receipt.operationId||'Unavailable')}</code></dd></div>
    </dl>
    <div class="platform-route-note" style="margin-top:14px">${CUI.icon('info',{size:18})}<p class="small">${esc(receipt.fulfilment)}</p></div>
    <button class="btn" id="merchantScannerReceiptClose" type="button" style="width:100%;margin-top:16px">Close receipt</button>`;
}
function openMerchantRedemptionScanner({
  businessId,branchId,saleId=null,customerName='',isCurrent=()=>true,onComplete=()=>{}
}={}){
  activeMerchantScannerCleanup();
  const overlay=document.createElement('div');
  overlay.className='modal appointment-detail-modal';
  overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');
  overlay.setAttribute('aria-labelledby','merchantScannerTitle');
  overlay.innerHTML=`<section class="modal-card" style="width:min(520px,calc(100vw - 24px))"><div class="row"><div><h2 id="merchantScannerTitle">Scan customer redemption</h2><p class="muted small" style="margin-top:5px">The reward remains pending until this business confirms the customer’s QR.</p></div><span class="spacer"></span><button class="btn ghost sm" id="merchantScannerClose" type="button" aria-label="Close scanner">${CUI.icon('close',{size:18})}</button></div>
    <div class="scanner-frame" id="merchantScannerFrame" hidden><video class="scanner-video" id="merchantScannerVideo" playsinline muted aria-label="Camera preview for customer redemption QR"></video></div>
    <div class="row" style="margin-top:14px"><button class="btn" id="merchantScannerCamera" type="button">${CUI.icon('scan',{size:18})}<span>Use camera</span></button><span class="muted small" id="merchantScannerCapability"></span></div>
    <div class="scanner-fallback"><label for="merchantScannerImage">Or choose a QR image</label><input id="merchantScannerImage" type="file" accept="image/*">
      <details style="margin-top:12px"><summary class="small">Camera unavailable?</summary><label for="merchantScannerToken">Paste the QR content</label><input id="merchantScannerToken" type="text" autocomplete="off" spellcheck="false"><button class="btn ghost sm" id="merchantScannerConfirm" type="button" style="margin-top:10px">Confirm redemption</button></details>
    </div><p id="merchantScannerStatus" class="muted small" role="status" aria-live="polite" style="margin-top:12px"></p></section>`;
  document.body.appendChild(overlay);
  recordProductInteractionV100('merchant.redemption_scan_started',businessId,{
    branchId,
    context:{action_key:'customer_redemption',entry_point:'quick_earn',locale:workspaceLocale,surface_version:'v100'}
  });
  const video=overlay.querySelector('#merchantScannerVideo');
  const frame=overlay.querySelector('#merchantScannerFrame');
  const status=overlay.querySelector('#merchantScannerStatus');
  const camera=overlay.querySelector('#merchantScannerCamera');
  let decoderAvailable=typeof globalThis.jsQR==='function';
  const cameraAvailable=!!navigator.mediaDevices?.getUserMedia;
  const scanCanvas=document.createElement('canvas'),scanContext=scanCanvas.getContext('2d',{willReadFrequently:true});
  let stream=null,frameHandle=0,submitting=false,closed=false,redemptionAttempt=null;
  const stopCamera=()=>{
    if(frameHandle)cancelAnimationFrame(frameHandle);frameHandle=0;
    if(stream)stream.getTracks().forEach(track=>track.stop());
    stream=null;if(video)video.srcObject=null;
  };
  const close=()=>{
    if(closed)return;closed=true;stopCamera();overlay.remove();
    if(activeMerchantScannerCleanup===close)activeMerchantScannerCleanup=()=>{};
  };
  activeMerchantScannerCleanup=close;
  const submit=async value=>{
    if(submitting||closed||!isCurrent())return;
    const payload=redemptionPayloadFromQr(value);
    const token=payload.token;
    if(!token){status.textContent='That is not a Peekaa redemption QR. Ask the customer to open Redeem again.';return}
    if(payload.kind==='growth'&&!saleId){
      status.textContent='This is a customer offer. Complete this customer’s purchase first, then use Redeem customer offer on the receipt.';
      return;
    }
    if(payload.kind!=='growth'&&!branchId){
      status.textContent='Choose an accessible branch before confirming this reward.';
      return;
    }
    const attemptFingerprint=`${payload.kind}:${token}:${saleId||''}`;
    if(!redemptionAttempt||redemptionAttempt.fingerprint!==attemptFingerprint){
      redemptionAttempt={fingerprint:attemptFingerprint,key:crypto.randomUUID()};
    }
    submitting=true;status.textContent='Confirming this redemption…';
    const response=payload.kind==='growth'
      ?await sb.rpc('redeem_growth_offer_v108',{
        p_business:businessId,p_token:token,p_sale:saleId,p_idempotency_key:redemptionAttempt.key
      })
      :await sb.rpc('merchant_scan_redemption_qr_v117',{
        p_business:businessId,p_branch:branchId,p_qr_token:token,
        p_idempotency_key:redemptionAttempt.key
      });
    let {data,error}=response;
    if(closed||!isCurrent())return;
    submitting=false;
    if(error){status.textContent=error.code==='PGRST202'||error.code==='42883'
      ?'Redemption scanning needs the latest Peekaa service update.'
      :payload.kind==='growth'
        ?'This offer could not be confirmed. Check that it belongs to this customer and purchase, and that it has not expired or already been used.'
        :'This redemption could not be confirmed. It may be expired, already used, or for another business.';return}
    if(data?.status!=='completed'&&data?.status!=='redeemed'){
      status.textContent=`Redemption was not completed (${String(data?.status||'unknown').replaceAll('_',' ')}).`;return;
    }
    redemptionAttempt=null;
    if(payload.kind==='growth'){
      data={...data,redemption_kind:'growth_offer',customer_name:customerName||'Customer'};
    }
    stopCamera();
    const panel=overlay.querySelector('.modal-card');
    panel.innerHTML=merchantRedemptionReceiptHtml(data);
    panel.querySelector('#merchantScannerReceiptClose').onclick=close;
    panel.querySelector('#merchantScannerReceiptClose').focus();
    toast(data?.replayed===true?'Redemption already confirmed':'Redemption confirmed');onComplete(data);
  };
  const decodeSource=(source,width,height)=>{
    if(!decoderAvailable||!scanContext||!width||!height)return '';
    const scale=Math.min(1,1200/Math.max(width,height));
    scanCanvas.width=Math.max(1,Math.round(width*scale));scanCanvas.height=Math.max(1,Math.round(height*scale));
    scanContext.drawImage(source,0,0,scanCanvas.width,scanCanvas.height);
    const pixels=scanContext.getImageData(0,0,scanCanvas.width,scanCanvas.height);
    return globalThis.jsQR(pixels.data,pixels.width,pixels.height,{inversionAttempts:'attemptBoth'})?.data||'';
  };
  const detectFrame=async()=>{
    if(closed||!stream||submitting)return;
    try{
      const value=decodeSource(video,video.videoWidth,video.videoHeight);
      if(value){
        await submit(value);
        if(!closed&&stream)frameHandle=requestAnimationFrame(detectFrame);
        return;
      }
    }catch{}
    frameHandle=requestAnimationFrame(detectFrame);
  };
  overlay.querySelector('#merchantScannerClose').onclick=close;
  overlay.addEventListener('click',event=>{if(event.target===overlay)close()});
  camera.disabled=!cameraAvailable;
  overlay.querySelector('#merchantScannerCapability').textContent=cameraAvailable
    ?'QR scanner will load when you open the camera.':'Live scanning is not supported by this browser. Choose a QR image instead.';
  camera.onclick=async()=>{
    if(camera.disabled)return;
    camera.disabled=true;status.textContent='Starting camera…';
    try{
      await loadScannerLibrary();decoderAvailable=true;
      stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});
      if(closed){stopCamera();return}
      video.srcObject=stream;await video.play();frame.hidden=false;status.textContent='Hold the QR inside the frame.';
      detectFrame();
    }catch{
      camera.disabled=false;status.textContent='Camera access was not available. Choose a QR image or paste the QR content.';
    }
  };
  overlay.querySelector('#merchantScannerImage').onchange=async event=>{
    const file=event.target.files?.[0];if(!file)return;
    status.textContent='Reading QR image…';
    try{
      await loadScannerLibrary();decoderAvailable=true;
      let source=null,revoke='';
      if(typeof createImageBitmap==='function')source=await createImageBitmap(file);
      else{
        revoke=URL.createObjectURL(file);source=new Image();
        await new Promise((resolve,reject)=>{source.onload=resolve;source.onerror=reject;source.src=revoke});
      }
      const value=decodeSource(source,source.width,source.height);
      source.close?.();if(revoke)URL.revokeObjectURL(revoke);
      if(!value)throw new Error('not found');
      await submit(value);
    }catch{status.textContent='No Peekaa redemption QR was found in that image.'}
  };
  overlay.querySelector('#merchantScannerConfirm').onclick=()=>submit(overlay.querySelector('#merchantScannerToken').value);
  overlay.querySelector('#merchantScannerToken').addEventListener('keydown',event=>{if(event.key==='Enter')submit(event.currentTarget.value)});
  overlay.querySelector('#merchantScannerClose').focus();
}
