  let canWrite=false,canComplete=false;
  routeMain.innerHTML=CUI.loadingState({title:'Appointments',iconName:'appointments'});
  const [
    {data:cl,error:clientError},{data:sv,error:serviceError},{data:stf,error:staffError},
    {data:branches,error:branchError},{data:staffBranches,error:staffBranchError},
    {data:serviceBranches,error:serviceBranchError},{data:staffHours,error:staffHoursError},
    {data:staffOffDays,error:staffOffDaysError},{data:branchHours,error:branchHoursError},
    {data:branchBreaks,error:branchBreaksError}
  ]=await Promise.all([
    fetchAllRowsResult(()=>sb.from('clients').select('id,full_name,phone,phone_norm,email',{count:'exact'}).eq('business_id',S.biz.id).order('full_name').order('id')),
    fetchAllRowsResult(()=>sb.from('services').select('id,name,variant_label,price_cents,duration_min,buffer_before_min,buffer_after_min',{count:'exact'}).eq('business_id',S.biz.id).eq('active',true).order('name').order('id')),
    fetchAllRowsResult(()=>sb.from('staff').select('id,full_name,user_id,calendar_color,phone,email',{count:'exact'}).eq('business_id',S.biz.id).eq('active',true).order('full_name').order('id')),
    fetchAllRowsResult(()=>sb.from('branches').select('id,name,is_default,timezone',{count:'exact'}).eq('business_id',S.biz.id).eq('active',true).order('name').order('id')),
    fetchAllRowsResult(()=>sb.from('staff_branches').select('staff_id,branch_id',{count:'exact'}).eq('business_id',S.biz.id).order('staff_id').order('branch_id')),
    fetchAllRowsResult(()=>sb.from('service_branches').select('service_id,branch_id',{count:'exact'}).eq('business_id',S.biz.id).order('service_id').order('branch_id')),
    fetchAllRowsResult(()=>sb.from('staff_hours').select('staff_id,weekday,starts_at,ends_at',{count:'exact'}).eq('business_id',S.biz.id).order('staff_id').order('weekday')),
    fetchAllRowsResult(()=>sb.from('staff_off_days').select('staff_id,starts_on,ends_on,reason',{count:'exact'}).eq('business_id',S.biz.id).order('staff_id').order('starts_on')),
    fetchAllRowsResult(()=>sb.from('branch_hours').select('branch_id,weekday,opens_at,closes_at',{count:'exact'}).eq('business_id',S.biz.id).order('branch_id').order('weekday')),
    fetchAllRowsResult(()=>sb.from('branch_breaks').select('branch_id,weekday,starts_at,ends_at',{count:'exact'}).eq('business_id',S.biz.id).order('branch_id').order('weekday').order('starts_at'))
  ]);
  if(!isCurrent())return;
  const loadError=clientError||serviceError||staffError||branchError||staffBranchError||serviceBranchError||
    staffHoursError||staffOffDaysError||branchHoursError||branchBreaksError;
  if(loadError)throw loadError;
  const clients=cl||[],staff=stf||[];
  const customerPhone=client=>String(client?.phone||client?.phone_norm||'').trim();
  const customerLabel=client=>{
    const name=String(client?.full_name||'Customer').trim()||'Customer',phone=customerPhone(client),email=String(client?.email||'').trim();
    return `${name} · ${phone||email||'no phone'}`;
  };
  const customerMatches=(client,query)=>{
    const needle=String(query||'').trim().toLocaleLowerCase(),digits=needle.replace(/\D/g,'');
    if(!needle)return true;
    const text=[client?.full_name,client?.phone,client?.phone_norm,client?.email].filter(Boolean).join(' ').toLocaleLowerCase();
    return text.includes(needle)||(digits.length>=3&&customerPhone(client).replace(/\D/g,'').includes(digits));
  };
  const staffNameCounts=staff.reduce((counts,person)=>{
    const key=String(person.full_name||'Staff').trim().toLocaleLowerCase();
    counts[key]=(counts[key]||0)+1;return counts;
  },{});
  const staffLabel=person=>{
    const name=String(person?.full_name||'Staff').trim()||'Staff',key=name.toLocaleLowerCase();
    if((staffNameCounts[key]||0)<2)return name;
    const contact=String(person?.phone||person?.email||'').trim();
    return `${name} · ${contact||`staff ${String(person?.id||'').slice(-4)}`}`;
  };
  const staffName=Object.fromEntries(staff.map(s=>[s.id,staffLabel(s)]));
  const staffColor=Object.fromEntries(staff.map(s=>[s.id,s.calendar_color||'#7C9CBF']));
  const myStaff=staff.find(s=>s.user_id===S.user.id);
  const canSeeAll=S.myRole==='owner'||S.myRole==='manager';
  const myBranchIds=new Set((staffBranches||[]).filter(x=>x.staff_id===myStaff?.id).map(x=>x.branch_id));
  const assignedBranches=(branches||[]).filter(b=>canSeeAll||myBranchIds.has(b.id));
  let projectionPairs;
  try{
    projectionPairs=await Promise.all(assignedBranches.map(async branch=>[
      branch.id,await loadBranchModuleProjection(branch.id)
    ]));
  }catch(error){
    if(!isCurrent())return;
    routeMain.innerHTML=CUI.errorState({title:'Appointments unavailable',message:'Branch access could not be loaded. Your settings were not changed.'});
    $('routeRetry').onclick=()=>{
      invalidateBranchModuleProjectionCache({businessId:S.biz.id});
      appointmentsPage().catch(fail);
    };
    return;
  }
  if(!isCurrent())return;
  const branchProjection=Object.fromEntries(projectionPairs);
  const visibleBranches=assignedBranches.filter(branch=>projectionCanRead(branchProjection[branch.id],'appointments'));
  let branchId=visibleBranches.some(b=>b.id===selectedBranchId)?selectedBranchId:
    (visibleBranches.find(b=>b.is_default)?.id||visibleBranches[0]?.id||'');
  if(branchId)selectedBranchId=branchId;
  const selectedProjection=branchProjection[branchId]||null;
  canWrite=projectionCanWrite(selectedProjection,'appointments');
  canComplete=canWrite&&projectionCanWrite(selectedProjection,'till')&&hasRoleCapability('create_sales');
  let staffFilter=canSeeAll?'all':(myStaff?myStaff.id:'all');
  let calendarServiceId='';
  let view='day',dayOffset=0,wkOff=0,listPage=0,calendarItems=[],calendarBlocks=[],bookingAttempt=null,
    rescheduleAttempt=null,blockCreateAttempt=null,closeAppointmentDialog=null,closeBlockDialog=null,
    dayAutoScrolled=false,calendarMinuteTimer=null;
  const blockDeleteAttempts=new Map();
  const availabilityGate=createLatestRequestGate(isCurrent);
  const bookingGate=createLatestRequestGate(isCurrent);
  const statusGate=createLatestRequestGate(isCurrent);
  const calendarGate=createLatestRequestGate(isCurrent);
  const rescheduleGate=createLatestRequestGate(isCurrent);
  const detailGate=createLatestRequestGate(isCurrent);
  const todaySg=new Date(Date.now()+8*3600000).toISOString().slice(0,10);
  const branchStaff=id=>staff.filter(s=>(staffBranches||[]).some(x=>x.branch_id===id&&x.staff_id===s.id));
  const branchServices=id=>(sv||[]).filter(service=>{
    const configured=(serviceBranches||[]).some(x=>x.service_id===service.id);
    return !configured||(serviceBranches||[]).some(x=>x.service_id===service.id&&x.branch_id===id);
  });
  const staffOpts=(sel,id)=>`${canSeeAll?`<option value="all" ${sel==='all'?'selected':''}>Everyone</option>`:''}`+
    branchStaff(id).map(s=>`<option value="${s.id}" ${sel===s.id?'selected':''}>${esc(staffLabel(s))}${myStaff&&myStaff.id===s.id?' (me)':''}</option>`).join('');
  const apptHeaderActions=canWrite?`<button class="btn ghost" id="openBlockTime">${CUI.icon('staff',{size:18})} Block time</button><button class="btn" id="openAppointmentForm">${CUI.icon('appointments',{size:18})} New appointment</button>`:'';
  routeMain.innerHTML=`<div data-workspace-i18n>${CUI.pageHeader({title:'Appointments',subtitle:'',iconName:'appointments',actions:apptHeaderActions,canWrite,moduleLabel:'Appointment scheduling'})}</div>
    ${!visibleBranches.length?CUI.card({title:'No appointment access',description:'This account has no active branch where Appointments is enabled.'}):`
    <div class="appointment-layout" id="appointmentLayout">
      ${canWrite?`<section class="card appointment-form-card" id="appointmentFormCard" aria-labelledby="newAppointmentTitle" hidden><div class="row"><h2 id="newAppointmentTitle" style="font-size:17px">New appointment</h2><span class="spacer"></span><button class="btn ghost sm" type="button" id="closeAppointmentForm">Close</button></div>
        <label for="apBranch">Branch</label><select id="apBranch">${visibleBranches.map(b=>`<option value="${b.id}" ${b.id===branchId?'selected':''}>${esc(b.name)}</option>`).join('')}</select>
        <label for="appointmentCustomerSearch">Customer</label><input id="appointmentCustomerSearch" type="search" inputmode="search" autocomplete="off" placeholder="Search name or phone" aria-controls="ac" aria-describedby="appointmentCustomerHelp">
        <select id="ac" aria-label="Matching customer" aria-describedby="appointmentCustomerHelp"></select>
        <p class="muted small" id="appointmentCustomerHelp" aria-live="polite" style="margin-top:6px">Names may repeat — use the phone number to confirm the right customer.</p>
        <label for="as">Service</label><select id="as"></select>
        <div id="generalDuration" hidden><label for="apDuration">Duration (minutes)</label><input id="apDuration" type="number" min="15" max="720" step="15" value="60"></div>
        <label for="astf">Assign to</label><select id="astf"></select>
        <p class="muted small" style="margin-top:6px">Auto-assign shares new bookings across eligible team members. Use Check staff to confirm this time.</p>
        <div class="split"><div><label for="ad">Date</label><input id="ad" type="date" value="${todaySg}"></div>
        <div><label for="at">Time</label><input id="at" type="time" value="10:00" step="900"></div></div>
        <label for="an">Note (optional)</label><textarea id="an" rows="2" maxlength="1000"></textarea>
        <div id="appointmentFormError" role="alert"></div><div id="scheduleSuggestion" aria-live="polite"></div>
        <div class="row" style="margin-top:16px;flex-wrap:wrap"><button class="btn ghost" id="checkAvailability">${CUI.icon('staff',{size:18})} Check staff</button>
          <button class="btn" id="ago">${CUI.icon('check',{size:18})} Book appointment</button></div>
      </section>`:''}
      <section class="card" style="${canWrite?'':'grid-column:1/-1'}"><div class="appointment-toolbar"><div class="v150-segment" role="tablist" aria-label="Appointment view"><button type="button" id="appointmentCalendarSeg" aria-pressed="true">Calendar</button><button type="button" id="appointmentListSeg" aria-pressed="false">List</button></div><span class="spacer"></span>
        
        
        <label class="sr-only" for="stfFilter">Appointment staff</label><span class="appointment-filter-with-icon">${CUI.icon('staff',{size:17,className:'appointment-filter-icon'})}<select id="stfFilter">${staffOpts(staffFilter,branchId)}</select></span>
        <span id="calendarOnlyControls" class="appointment-toolbar" style="gap:6px;padding:0;border:0;background:transparent">
          <button class="qbtn act" id="vDay">Day</button><button class="qbtn" id="vWeek">Week</button>
<button class="qbtn" id="wkPrev" aria-label="Previous period">${CUI.icon('back',{size:17})}</button><button class="qbtn" id="wkNext" aria-label="Next period">${CUI.icon('forward',{size:17})}</button>
        </span>
        <details class="appointment-more"><summary class="qbtn">More</summary><div class="appointment-more-menu"><button class="qbtn" id="apPrint">Print</button><button class="qbtn" id="apCsv">Download CSV</button></div></details></div>
        <div class="appointment-list-filters" id="appointmentListFilters" hidden>
          <div><label for="appointmentListFrom">From</label><input type="date" id="appointmentListFrom" class="appt-date-narrow-v251" value="${todaySg}"></div>
          <div><label for="appointmentListTo">To</label><input type="date" id="appointmentListTo" class="appt-date-narrow-v251" value="${shiftSgDateInput(todaySg,7)}"></div>
          <div><label for="appointmentListStatus">Appointment status</label><select id="appointmentListStatus"><option value="">All statuses</option><option value="booked">Booked</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option><option value="no_show">No-show</option></select></div>
          <div class="row" style="gap:8px;align-items:end"><button type="button" class="btn sm" id="appointmentListApply">Apply filters</button><button type="button" class="btn ghost sm" id="appointmentListClear">Clear filters</button></div>
          <div class="row" style="grid-column:1/-1;gap:8px;flex-wrap:wrap"><button type="button" class="qbtn" data-appt-preset="today">Today</button><button type="button" class="qbtn" data-appt-preset="next7">Next 7 days</button><button type="button" class="qbtn" data-appt-preset="past7">Past 7 days</button><button type="button" class="qbtn" data-appt-preset="month">This month</button></div>
        </div>
        <div id="calendarSelection"></div><div id="alist" style="margin-top:12px"><p class="muted small">Loading calendar…</p></div>
      </section>
    </div>`}`;
  if(!visibleBranches.length)return;
  const appointmentLayout=$('appointmentLayout'),appointmentFormCard=$('appointmentFormCard');
  function closeNewAppointmentForm(){
    if(!appointmentFormCard)return;
    appointmentFormCard.hidden=true;appointmentLayout?.classList.remove('form-open');
    $('openAppointmentForm')?.focus();
  }
  function openNewAppointmentForm({date='',staffId='',time='',serviceId=''}={}){
    if(!appointmentFormCard)return;
    appointmentFormCard.hidden=false;appointmentLayout?.classList.add('form-open');
    if(date&&$('ad'))$('ad').value=date;
    if(time&&$('at'))$('at').value=time;
    if(staffId&&$('astf')&&[...$('astf').options].some(option=>option.value===staffId))$('astf').value=staffId;
    if(serviceId&&$('as')&&[...$('as').options].some(option=>option.value===serviceId)){
      $('as').value=serviceId;$('generalDuration').hidden=true;
    }
    appointmentFormCard.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});
    requestAnimationFrame(()=>$('appointmentCustomerSearch')?.focus());
  }
  function closeBlockedTimeDialog({restoreFocus=true}={}){
    if(!closeBlockDialog)return;
    const close=closeBlockDialog;closeBlockDialog=null;close({restoreFocus});
  }
  function openBlockedTimeDialog({date=addDays(todaySg,dayOffset)}={}){
    closeBlockedTimeDialog();
    const people=branchStaff(branchId);
    const dialog=document.createElement('div');
    dialog.className='modal';dialog.setAttribute('role','dialog');dialog.setAttribute('aria-modal','true');
    dialog.setAttribute('aria-labelledby','blockTimeTitle');dialog.tabIndex=-1;
    dialog.innerHTML=`<div class="modal-card" style="width:min(520px,100%)"><div class="row"><div><h2 id="blockTimeTitle">Block time</h2><p class="muted small" style="margin-top:4px">Mark one team member unavailable in this branch. Customers never see the reason.</p></div><span class="spacer"></span><button type="button" class="btn ghost sm" id="blockTimeClose" aria-label="Close blocked time">Close</button></div>
      ${people.length?`<form id="blockTimeForm" style="margin-top:16px">
        <label for="blockTimeStaff">Team member</label><select id="blockTimeStaff" required>${people.map(person=>`<option value="${person.id}">${esc(staffLabel(person))}</option>`).join('')}</select>
        <label for="blockTimeDate">Date</label><input id="blockTimeDate" type="date" required value="${esc(date)}">
        <div class="split"><div><label for="blockTimeStart">Start</label><input id="blockTimeStart" type="time" step="900" required value="14:00"></div><div><label for="blockTimeEnd">End</label><input id="blockTimeEnd" type="time" step="900" required value="15:00"></div></div>
        <label for="blockTimeReason">Reason (optional)</label><input id="blockTimeReason" maxlength="160" autocomplete="off" placeholder="e.g. Supplier training">
        <div id="blockTimeError" role="alert"></div><div class="row" style="margin-top:16px"><span class="spacer"></span><button type="button" class="btn ghost" id="blockTimeCancel">Cancel</button><button type="submit" class="btn" id="blockTimeSave">Save block</button></div>
      </form>`:`<div class="cui-empty" style="margin-top:18px">${CUI.icon('staff',{size:38})}<h3>No team member assigned</h3><p>Assign an active team member to this branch before blocking time.</p></div>`}
    </div>`;
    document.body.append(dialog);
    const close=()=>closeBlockedTimeDialog();
    closeBlockDialog=CUI.activateDialog(dialog,{onClose:close,initialFocus:people.length?'#blockTimeStaff':'#blockTimeClose'});
    $('blockTimeClose').onclick=close;dialog.onclick=event=>{if(event.target===dialog)close()};
    if(!people.length)return;
    $('blockTimeCancel').onclick=close;
    $('blockTimeForm').onsubmit=async event=>{
      event.preventDefault();
      const dateValue=$('blockTimeDate').value,startValue=$('blockTimeStart').value,endValue=$('blockTimeEnd').value;
      const starts=sgIso(`${dateValue}T${startValue}`),ends=sgIso(`${dateValue}T${endValue}`);
      const errorHost=$('blockTimeError'),save=$('blockTimeSave');
      if(!starts||!ends||new Date(ends)<=new Date(starts)){
        errorHost.innerHTML='<div class="err">End time must be later than start time on the same day.</div>';return;
      }
      const request={p_business:S.biz.id,p_branch:branchId,p_staff:$('blockTimeStaff').value,
        p_starts:starts,p_ends:ends,p_reason:$('blockTimeReason').value.trim()||null};
      const fingerprint=JSON.stringify(request);
      if(!blockCreateAttempt||blockCreateAttempt.fingerprint!==fingerprint){
        blockCreateAttempt={fingerprint,key:crypto.randomUUID()};
      }
      save.disabled=true;errorHost.innerHTML='';
      const {data,error}=await sb.rpc('create_staff_blocked_time_v120',{
        ...request,p_idempotency_key:blockCreateAttempt.key
      });
      if(!isCurrent()||!dialog.isConnected)return;
      save.disabled=false;
      if(error){
        errorHost.innerHTML=`<div class="err">${esc(error.message||'Blocked time could not be saved. Retry keeps the same request.')}</div>`;return;
      }
      blockCreateAttempt=null;close();
      toast(data?.replayed?'Blocked time was already saved':'Time blocked');
      loadCalendar().catch(fail);
    };
  }
  if(canWrite){
    $('openAppointmentForm').onclick=()=>openNewAppointmentForm({date:addDays(todaySg,dayOffset)});
    $('openBlockTime').onclick=()=>openBlockedTimeDialog();
    $('closeAppointmentForm').onclick=closeNewAppointmentForm;
  }
  function renderCustomerOptions(query='',selectedId=''){
    if(!canWrite||!$('ac'))return;
    const matches=clients.filter(client=>customerMatches(client,query));
    $('ac').innerHTML=`<option value="">${clients.length?'Choose a customer':'Add a customer first'}</option>${matches.map(client=>`<option value="${client.id}">${esc(customerLabel(client))}</option>`).join('')}`;
    $('ac').value=matches.some(client=>client.id===selectedId)?selectedId:'';
    const help=$('appointmentCustomerHelp');
    if(help)help.textContent=query
      ?`${matches.length} matching customer${matches.length===1?'':'s'}. Names may repeat — confirm the phone number.`
      :'Names may repeat — use the phone number to confirm the right customer.';
  }
  function syncFormOptions(){
    if(!canWrite)return;
    const services=branchServices(branchId),people=branchStaff(branchId);
    /* V217. Owner, on this dropdown: "instead of general visit, put ...". A business that has
       real services was still offered "General visit" first and by default, so the common case —
       booking an actual service, with its own duration and buffers — took an extra step, and an
       untouched form booked an unnamed 60-minute hold instead of the thing being sold. Real
       services now lead and the first one is preselected. "General visit" stays, last and named
       for what it is, because a walk-in with no service chosen is a real thing to book. */
    const previousServiceV217=$('as').value;
    $('as').innerHTML=`${services.map(s=>`<option value="${s.id}" data-duration="${s.duration_min}" data-buffer-before="${s.buffer_before_min||0}" data-buffer-after="${s.buffer_after_min||0}">${esc(serviceDisplayName(s))}</option>`).join('')}<option value="">${services.length?'No specific service · general visit':'General visit'}</option>`;
    $('as').value=[...$('as').options].some(option=>option.value===previousServiceV217)
      ?previousServiceV217
      :(services[0]?.id||'');
    $('astf').innerHTML=`<option value="auto">Auto-assign · fair rotation</option>${people.map(s=>`<option value="${s.id}">${esc(staffLabel(s))}</option>`).join('')}`;
    $('generalDuration').hidden=$('as').value!=='';
  }
  const selectedDuration=()=>Number($('as')?.selectedOptions?.[0]?.dataset?.duration||$('apDuration')?.value||60);
  const selectedStart=()=>sgIso(`${$('ad')?.value||''}T${$('at')?.value||''}`);
  const sgInput=iso=>{const d=new Date(new Date(iso).getTime()+8*3600000);return d.toISOString().slice(0,16)};
  function invalidateFormRequests({clearSuggestions=true,availability=true}={}){
    if(availability)availabilityGate.invalidate();
    bookingGate.invalidate();bookingAttempt=null;
    if($('checkAvailability'))$('checkAvailability').disabled=false;
    if($('ago'))$('ago').disabled=false;
    if(clearSuggestions&&$('scheduleSuggestion'))$('scheduleSuggestion').innerHTML='';
  }
  /* V217 — two owner reports about this one panel.
     (5) "i selected kelvin - why it show devi next best time?" It always led with available[0],
         the FAIREST person, even when the person the owner had actually chosen was free. Being
         told about Devi after choosing Kelvin reads as the system overruling the choice. It now
         answers the question that was asked — is the person I picked free? — and offers the
         fairer option as a suggestion underneath, which is what it always was.
     (6) "recent appointment - how recent?" The count had no stated window (it was a hidden 30
         days). The window is now on the label AND selectable, and it drives the server's
         fairness ranking too, so changing it changes the advice rather than just the wording. */
  const RECENT_WINDOWS_V217=[{days:1,label:'day'},{days:3,label:'3 days'},{days:7,label:'week'},{days:30,label:'month'}];
  let recentWindowDaysV217=30;
  const recentWindowLabelV217=days=>RECENT_WINDOWS_V217.find(w=>w.days===days)?.label||'month';
  function renderSuggestions(payload,conflict=false){
    const host=$('scheduleSuggestion');if(!host)return;
    const available=payload?.available_staff||[],next=payload?.next_best_slots||[];
    const selected=$('astf').value;
    const isAuto=selected==='auto';
    const selectedEntry=available.find(x=>x.staff_id===selected)||null;
    const selectedFree=isAuto||!!selectedEntry;
    const fairest=available[0];
    const windowLabel=recentWindowLabelV217(recentWindowDaysV217);
    /* A fairer alternative is only worth naming when it is genuinely fairer — same-count
       staff are not an argument for changing the owner's choice. */
    const fairerThanSelected=selectedEntry&&fairest&&fairest.staff_id!==selectedEntry.staff_id
      &&Number(fairest.recent_appointments)<Number(selectedEntry.recent_appointments)?fairest:null;
    const headline=!available.length
      ?'No eligible staff member is free at this time.'
      :selectedEntry
      ?(fairerThanSelected
        ?workspaceTemplateHtmlV97('selectedStaffFreeFairer',{
            staff:staffName[selectedEntry.staff_id]||selectedEntry.staff_name,
            alt:staffName[fairerThanSelected.staff_id]||fairerThanSelected.staff_name})
        :workspaceTemplateHtmlV97('selectedStaffFree',{
            staff:staffName[selectedEntry.staff_id]||selectedEntry.staff_name}))
      :workspaceTemplateHtmlV97(available.length===1?'availableStaff':'availableStaffMany',
          {staff:staffName[fairest.staff_id]||fairest.staff_name,count:available.length});
    host.innerHTML=`<div class="schedule-suggestion">
      <h3>${conflict||!selectedFree?'That person is not free':'Availability checked'}</h3>
      <p class="muted small" style="margin-top:5px">${headline}</p>
      <label for="recentWindowV217" class="small" style="display:block;margin-top:11px">Count appointments from the last</label>
      <select id="recentWindowV217" style="margin-top:4px">${RECENT_WINDOWS_V217.map(w=>`<option value="${w.days}" ${w.days===recentWindowDaysV217?'selected':''}>${esc(w.label)}</option>`).join('')}</select>
      <p class="muted small" style="margin:5px 0 0">This is the window used to decide who has had the fewest appointments.</p>
      ${available.length?`<div class="schedule-suggestion-actions">${available.map(person=>`<button type="button" class="btn ghost sm suggestionStaff${person.staff_id===selected?' is-selected-v217':''}" data-staff="${person.staff_id}" data-staff-name="${esc(staffName[person.staff_id]||person.staff_name)}">${CUI.icon('staff',{size:16})} <span data-merchant-content>${esc(staffName[person.staff_id]||person.staff_name)}</span> · ${workspaceTemplateHtmlV97('recentInWindow',{count:person.recent_appointments,window:windowLabel})}</button>`).join('')}</div>`:''}
      ${next.length?`<p class="muted small" style="margin-top:11px">Next best times today</p><div class="schedule-suggestion-actions">${next.map(slot=>`<button type="button" class="btn ghost sm suggestionTime" data-start="${esc(slot.starts_at)}" data-staff="${slot.staff_id}">${esc(sgt(slot.starts_at))} · ${esc(staffName[slot.staff_id]||slot.staff_name)}</button>`).join('')}</div>`:''}
    </div>`;
    const windowSelect=$('recentWindowV217');
    if(windowSelect)windowSelect.onchange=()=>{
      recentWindowDaysV217=Number(windowSelect.value)||30;
      renderAvailability();
    };
    host.querySelectorAll('.suggestionStaff').forEach(button=>button.onclick=()=>{
      invalidateFormRequests();$('astf').value=button.dataset.staff;
      CUI.announce(workspaceTemplateTextV97('itemSelected',{item:button.dataset.staffName||button.textContent.trim()}));
    });
    host.querySelectorAll('.suggestionTime').forEach(button=>button.onclick=()=>{
      const local=sgInput(button.dataset.start);invalidateFormRequests();
      $('ad').value=local.slice(0,10);$('at').value=local.slice(11,16);$('astf').value=button.dataset.staff;
      renderAvailability();
    });
  }
  /* V220 — the clash prompt. Two routes out, both one tap, and no dead end: either move the
     time (these are the chosen person's own free times) or hand the booking to someone who IS
     free. Choosing either only fills the form — the owner still presses Book, so nothing is
     booked behind their back. */
  function openClashPromptV220({staffLabel='',payload={}}={}){
    const times=(payload.next_best_slots||[]).slice(0,4);
    const free=(payload.available_staff||[]).slice(0,4);
    const who=staffLabel?esc(staffLabel):'That team member';
    document.querySelector('#clashPromptV220')?.remove();
    document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="clashPromptV220" role="dialog" aria-modal="true" aria-labelledby="clashTitleV220" tabindex="-1">
      <section class="modal-card" style="max-width:520px">
        <div class="row"><div><p class="eyebrow">Not booked</p><h2 id="clashTitleV220" style="margin-top:4px">${who} is already busy then</h2></div><span class="spacer"></span><button type="button" class="btn ghost sm" id="clashCloseV220" aria-label="Close">Close</button></div>
        <p class="muted small">Nothing has been booked. Pick another time, or give this booking to someone who is free.</p>
        ${times.length?`<b class="small" style="display:block;margin-top:14px">${staffLabel?`Other times ${esc(staffLabel)} is free`:'Other times that work'}</b>
          <div class="schedule-suggestion-actions">${times.map(slot=>`<button type="button" class="btn ghost sm" data-clash-time="${esc(slot.starts_at)}" data-clash-time-staff="${esc(slot.staff_id||'')}">${esc(sgt(slot.starts_at))}${staffLabel?'':` · ${esc(staffName[slot.staff_id]||slot.staff_name||'')}`}</button>`).join('')}</div>`
          :`<p class="small" style="margin-top:14px">${staffLabel?`${esc(staffLabel)} has no other free time left today.`:'No other time is free later today.'}</p>`}
        ${free.length?`<b class="small" style="display:block;margin-top:16px">Free at this time</b>
          <div class="schedule-suggestion-actions">${free.map(person=>`<button type="button" class="btn ghost sm" data-clash-staff="${esc(person.staff_id)}">${esc(staffName[person.staff_id]||person.staff_name||'')}</button>`).join('')}</div>`
          :'<p class="small" style="margin-top:16px">Nobody else is free at this time either.</p>'}
        <div class="row" style="margin-top:18px"><button type="button" class="btn ghost sm" id="clashCancelV220">Keep editing</button></div>
      </section></div>`);
    const dialog=$('clashPromptV220');
    let deactivate;
    const close=()=>deactivate?.();
    deactivate=CUI.activateDialog(dialog,{onClose:close,initialFocus:'#clashCloseV220'});
    $('clashCloseV220').onclick=close;
    $('clashCancelV220').onclick=close;
    dialog.querySelectorAll('[data-clash-time]').forEach(button=>button.onclick=()=>{
      const local=sgInput(button.dataset.clashTime);
      invalidateFormRequests();
      $('ad').value=local.slice(0,10);$('at').value=local.slice(11,16);
      if(button.dataset.clashTimeStaff)$('astf').value=button.dataset.clashTimeStaff;
      close();renderAvailability();
    });
    dialog.querySelectorAll('[data-clash-staff]').forEach(button=>button.onclick=()=>{
      invalidateFormRequests();
      $('astf').value=button.dataset.clashStaff;
      close();renderAvailability();
    });
  }
  async function renderAvailability(){
    const stillCurrent=availabilityGate.begin();
    const starts=selectedStart(),duration=selectedDuration(),formError=$('appointmentFormError');
    if(!starts||!Number.isInteger(duration)||duration<15||duration>720){
      formError.innerHTML='<div class="err">Choose a valid date, time and duration.</div>';return null;
    }
    formError.innerHTML='';$('checkAvailability').disabled=true;
    const {data,error}=await sb.rpc('suggest_appointment_staff_v47',{p_business:S.biz.id,p_branch:branchId,
      p_service:$('as').value||null,p_starts:starts,p_duration_minutes:duration,p_limit:5,
      p_recent_days:recentWindowDaysV217,
      /* V220: when a teammate is chosen, the alternative TIMES must be theirs. Auto-assign
         sends null, so the fair rotation still decides who each suggested time belongs to. */
      p_staff:$('astf').value==='auto'?null:$('astf').value});
    if(!stillCurrent())return null;
    $('checkAvailability').disabled=false;
    if(error){formError.innerHTML=`<div class="err">${esc(error.message)}</div>`;return null}
    renderSuggestions(data||{});return data;
  }
  if(canWrite){
    renderCustomerOptions();
    syncFormOptions();
    /* Customer 360 deep-link: a customer handed in via pendingApptClientId (captured above as
       apptPrefillClient) pre-selects that customer in the existing #ac dropdown — same select,
       no new query. The form is then brought into view so staff land ready to pick a time. */
    /* V218: opens with the date already on the form (todaySg, set when #ad was rendered).
       V217 called addDays(todaySg,dayOffset) here, but addDays is a `const` declared further
       down this function — this line runs during the synchronous render, before that binding
       exists, so it threw "Cannot access 'addDays' before initialization" and took the whole
       Appointments page down. Passing no date leaves #ad's own value untouched. */
    if(apptOpenFormV217&&!apptPrefillClient)openNewAppointmentForm({});
    if(apptPrefillClient){
      openNewAppointmentForm({date:todaySg});
      const clientSelect=$('ac');
      if(clientSelect&&[...clientSelect.options].some(o=>o.value===apptPrefillClient)){
        clientSelect.value=apptPrefillClient;
      }
    }
    $('appointmentCustomerSearch').oninput=()=>{
      const selected=$('ac').value;
      renderCustomerOptions($('appointmentCustomerSearch').value,selected);
      invalidateFormRequests({clearSuggestions:false,availability:false});
    };
    $('as').onchange=()=>{$('generalDuration').hidden=$('as').value!=='';invalidateFormRequests()};
    ['ad','at','astf','apDuration'].forEach(id=>$(id).onchange=()=>invalidateFormRequests());
    $('ac').onchange=()=>invalidateFormRequests({clearSuggestions:false,availability:false});
    $('an').oninput=()=>invalidateFormRequests({clearSuggestions:false,availability:false});
    $('checkAvailability').onclick=renderAvailability;
    $('apBranch').onchange=()=>{selectedBranchId=$('apBranch').value;appointmentsPage().catch(fail)};
    $('ago').onclick=async()=>{
      const starts=selectedStart(),duration=selectedDuration(),assignment=$('astf').value;
      if(!$('ac').value)return $('appointmentFormError').innerHTML='<div class="err">Choose a customer.</div>';
      if(!starts||!Number.isInteger(duration)||duration<15||duration>720)return $('appointmentFormError').innerHTML='<div class="err">Choose a valid date, time and duration.</div>';
      const request={p_business:S.biz.id,p_client:$('ac').value,p_branch:branchId,p_service:$('as').value||null,
        p_starts:starts,p_duration_minutes:duration,p_requested_staff:assignment==='auto'?null:assignment,
        p_assignment_mode:assignment==='auto'?'round_robin':'manual',p_note:$('an').value.trim()||null};
      const fingerprint=JSON.stringify(request);
      if(!bookingAttempt||bookingAttempt.fingerprint!==fingerprint)bookingAttempt={fingerprint,key:crypto.randomUUID()};
      const stillCurrent=bookingGate.begin();
      $('ago').disabled=true;$('appointmentFormError').innerHTML='';
      const {data,error}=await sb.rpc('book_appointment_smart_v47',{...request,p_idempotency_key:bookingAttempt.key});
      if(!stillCurrent())return;
      $('ago').disabled=false;
      if(error){$('appointmentFormError').innerHTML=`<div class="err">${esc(error.message)}</div>`;return}
      if(data?.status==='conflict'){
        /* V220. Owner: "if the timing is clashed, when press book appointment - should pop up
           prompt to notify user, direct them to change timing / suggest free staff".
           It used to redraw the suggestion panel further down the page and announce to screen
           readers only — nothing visibly happened where the owner was looking, so a clash read
           as the button doing nothing. Now it interrupts, and the times it offers are the chosen
           person's (p_staff below), with whoever IS free as the other route. */
        renderSuggestions(data.suggestions||{},true);
        CUI.announce('Appointment clash found. Choose an available staff member or another time.',{assertive:true});
        const fresh=await sb.rpc('suggest_appointment_staff_v47',{p_business:S.biz.id,p_branch:branchId,
          p_service:$('as').value||null,p_starts:starts,p_duration_minutes:duration,p_limit:5,
          p_recent_days:recentWindowDaysV217,p_staff:assignment==='auto'?null:assignment});
        if(!stillCurrent())return;
        openClashPromptV220({
          staffLabel:assignment==='auto'?'':(staffName[assignment]||''),
          payload:(fresh.error?null:fresh.data)||data.suggestions||{}
        });
        return;
      }
      bookingAttempt=null;$('an').value='';$('scheduleSuggestion').innerHTML='';
      toast(data?.replayed?'Appointment already booked — no duplicate created':workspaceTemplateTextV97('bookedWith',{staff:data?.staff_name||staffName[data?.staff_id]||workspaceTranslationV97('staff')}));
      closeNewAppointmentForm();
      loadCalendar();
    };
  }
